// engine/routes.ts — **담당자가 친 말이 어디로 가는지**를 한 곳에 적은 표.
//
// ⚠ 이 파일은 **실행하지 않는다.** 라우팅은 지금처럼 dispatcher.ts와 agentloop.ts가 한다 —
//   잘 돌고 있는 것을 건드리는 위험을 지지 않기 위해서다(147상황 140/147·평가 게이트 3축 통과).
//   여기 표는 **보이게 하고, 어긋나면 막는** 몫만 진다:
//     · routes.test.ts가 이 표와 실제 코드를 **양방향으로** 대조한다 — 표가 낡으면 시험이 깨진다
//       ① 표 → 코드: 표에 적힌 판별자가 코드에 실재하고 실제로 불리는가
//       ② 코드 → 표: dispatcher의 결정적 체인에 있는 갈래가 표에 **빠짐없이** 있는가
//     · tools/route-explain.mjs가 "이 말은 어디로 갑니까?"를 한 줄로 답한다
//
// ★★ 왜 ②(역방향)가 생겼나 (실측 2026-09-04 · 00b47a67 뒤)
//   ①만 있던 시절, 이 표는 **적힌 것만** 검사받았다. 그래서 dispatcher가 실제로 보는 결정적
//   갈래 37개 중 **26개가 표에 아예 없었다** — isFindingListAsk·isMyWorkAsk·screenNameCard·
//   isHardeningStatusAsk·이름으로화면찾기·findHowTo·isOutOfScope·isTooVague·장애질문인가·
//   침해사고질문인가·isScopeCommand·isScenarioAsk·faqAnswerFor·결재승인요청_RE …
//   시험은 내내 초록이었고, 그 결과 route-explain이 「미조치 취약점 뭐 있어?」를 「search로
//   갑니다」라고 **거짓 설명**했다. 빠뜨린 것은 원리상 ①이 못 본다 — 그래서 ②를 둔다.
//   같은 날 층 번호도 실제 순서와 **거꾸로** 적혀 있던 것이 드러났다(아래 `층` 머리글).
//
// 왜 필요한가(2026-08-03 실측):
//   길이 **여덟 겹·규칙 서른다섯**으로 자랐고, 두 파일에 흩어져 **배열 순서가 곧 우선순위**다.
//   2026-08-02에 내가 직접 그 함정을 밟았다 — 넓은 규칙을 앞에 넣어 today를 가로챘고
//   라우팅이 100% → 96.9%로 떨어졌다. "이 말이 어디로 갈지"를 아무도 한눈에 못 본다.
//   연구도 같은 지적을 한다: 잘못 분류된 입력은 여러 단계를 타고 내려가며 환각을 키운다.

/**
 * 어느 층에서 갈리는가. **번호 = 그 층이 결정적 체인에서 처음 나오는 `차례`**
 * (dispatcher.결정적체인() — 코드가 실제로 보는 순서 그대로).
 *
 * ⚠ **층은 묶음이지 순서가 아니다.** 같은 층이 체인 여기저기에 흩어져 있다 —
 *   특수경로는 [1]에서 시작해 [36]까지 아홉 군데로 나뉘고, 되묻기는 [3]과 [31]에 따로 있다.
 *   그러니 「이 말이 저 말보다 먼저인가」는 **층이 아니라 `차례`로** 본다(`순서대로()` 참고).
 * ⚠ 2026-09-04까지 이 번호는 실제와 **거꾸로** 적혀 있었다(화면안내 30 · 체크선택 40 · 내업무 50).
 *   코드는 내업무[7] → 체크선택[10] → 화면안내[20] 순으로 본다. 번호를 손으로 매기지 말 것 —
 *   routes.test.ts가 「층 번호 = 그 층 첫 차례」를 잰다.
 */
export const 층 = {
  가드레일: 0,       // [0]  해로운 요청 — 모델에 닿기 전에 끝낸다
  특수경로: 1,       // [1]  dispatcher가 직접 답하는 결정적 기능들(체인 곳곳에 흩어져 있다)
  되묻기: 3,         // [3]  뜻이 안 잡히는 말 — 지어내지 않고 되묻는다
  내업무: 7,         // [7]  "○○ 완료" · "○○ 어떻게 해" — 내 할 일과 이름이 겹칠 때만
  체크선택: 10,      // [10] 목록에서 체크해 고른 것 — 해석할 것이 없다
  화면안내: 20,      // [20] "이 화면 뭐 해?" · "○○ 어디서 해?" — screenguide
  강제도구: 37,      // [37] forcedToolFor — 문구가 명백하면 그 도구로 못박는다(체인의 맨 끝)
  잡담: 90,          // 체인 **밖** — 인사·감사는 LLM 답 경로(llm.smallTalkReply)가 처리한다
  모델선택: 99,      // 위에서 안 걸리면 LLM이 도구를 고른다
} as const;

export type 층이름 = keyof typeof 층;

export interface 길 {
  /** 사람이 부르는 이름 */
  이름: string;
  층: 층이름;
  /** 어디서 실행되는가 — 시험이 이 파일을 열어 대조한다 */
  파일: "dispatcher.ts" | "agentloop.ts" | "gateway.ts";
  /** 코드에 있는 판별자 이름(정규식 상수·함수). 시험이 실재를 확인한다 */
  판별: string;
  /** 어디로 보내는가 — 도구 이름이거나 특수 경로 설명 */
  도착: string;
  /** 왜 이 길이 있는가. **이유 없는 길은 시험이 막는다** */
  왜: string;
  /**
   * 결정적 체인에서 **몇 번째로 보는가** — dispatcher.결정적체인()의 `차례`와 같아야 한다.
   * 체인 밖의 길(FORCED_INTENTS 개별 규칙·잡담)에는 없다.
   */
  차례?: number;
  /**
   * dispatchInstructionCore에서 이 갈래를 여는 **코드 글자 그대로**.
   * 역방향 감시(코드 체인 ⊆ 표)가 이 글자로 대조하므로 **손으로 지어내지 말고** dispatcher의
   * `감시` 칸에서 그대로 옮긴다 — 두 벌이 어긋나면 시험이 어느 것이 빠졌는지 알려 준다.
   */
  감시?: string;
}

