/**
 * **실제로 보는 순서대로** 정렬한 목록 — 화면·도구가 순서를 보여줄 때 쓴다.
 *
 * ⚠ 정렬 열쇠는 `층`이 아니라 **`차례`**다. 층으로 줄 세우면 거짓이 된다 —
 *   같은 층이 체인 여기저기에 흩어져 있어서, 되묻기[31]이 특수경로[11]보다 앞으로 올라온다.
 *   차례가 없는 길(FORCED_INTENTS 개별 규칙·잡담)만 층 번호로 잰다(그것들은 한 층 안에 모여 있다).
 */
export function 순서대로(): 길[] {
  const 열쇠 = (r: 길) => r.차례 ?? 층[r.층];
  return [...길목록].sort((a, b) => 열쇠(a) - 열쇠(b));
}
